<section class="container section"><p class="eyebrow">ORGANIZÁ TUS PIEZAS</p><h1>Categorías.</h1><?php if($error): ?><div class="alert"><?= e($error) ?></div><?php endif ?><div class="checkout-layout"><div class="form-panel"><?php foreach($categories as $c): ?><form method="post" class="category-row"><?= csrf() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><label><span class="sr-only">Nombre de categoría</span><input name="name" value="<?= e($c['name']) ?>" maxlength="100" required></label><button class="btn secondary small">Guardar</button><button class="text-button danger" name="delete" value="1" data-confirm="¿Eliminar esta categoría? Los productos conservarán sus otras categorías.">Eliminar</button></form><?php endforeach ?><?php if(!$categories): ?><p>Todavía no agregaste categorías.</p><?php endif ?></div><aside class="summary"><h2>Nueva categoría</h2><form method="post"><?= csrf() ?><label>Nombre<input name="name" maxlength="100" required></label><button class="btn full">Crear categoría +</button></form></aside></div></section>
